require_once __DIR__.'/../includes/bootstrap.php';if(empty($_SESSION['reset_customer_id']))redirect('/auth/forgot-password.php');$title='Verify OTP';$errors=[];$cid=(int)$_SESSION['reset_customer_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'verify';if($action==='resend'){if(time()-(int)($_SESSION['reset_last_sent']??0)<60){$errors[]='Please wait for the countdown to finish before requesting another OTP.';}else{$q=$pdo->prepare('SELECT email,full_name FROM customers WHERE customer_id=? AND status="ACTIVE"');$q->execute([$cid]);$c=$q->fetch();if(!$c)redirect('/auth/forgot-password.php');$otp=(string)random_int(100000,999999);$exp=date('Y-m-d H:i:s',time()+600);$pdo->prepare('DELETE FROM password_reset_otps WHERE customer_id=?')->execute([$cid]);$pdo->prepare('INSERT INTO password_reset_otps(customer_id,otp_hash,expires_at) VALUES(?,?,?)')->execute([$cid,password_hash($otp,PASSWORD_DEFAULT),$exp]);if(send_customer_otp_html($c['email'],$otp)){$_SESSION['reset_last_sent']=time();$_SESSION['reset_expires']=$exp;$_SESSION['flash_otp']='A new OTP was sent to your registered email.';}else{$errors[]='The new OTP could not be sent. Please try again.';}}}else{$otp=trim((string)($_POST['otp']??''));$s=$pdo->prepare('SELECT * FROM password_reset_otps WHERE customer_id=? ORDER BY reset_id DESC LIMIT 1');$s->execute([$cid]);$r=$s->fetch();if(!$r||strtotime($r['expires_at'])<time())$errors[]='This OTP has expired. Request a new one.';elseif((int)$r['attempts']>=5)$errors[]='Too many incorrect attempts. Request a new OTP.';elseif(!preg_match('/^\d{6}$/',$otp)||!password_verify($otp,$r['otp_hash'])){$pdo->prepare('UPDATE password_reset_otps SET attempts=attempts+1 WHERE reset_id=?')->execute([(int)$r['reset_id']]);$errors[]='Incorrect OTP.';}else{$pdo->prepare('UPDATE password_reset_otps SET verified_at=NOW() WHERE reset_id=?')->execute([(int)$r['reset_id']]);$_SESSION['reset_verified']=(int)$r['reset_id'];redirect('/auth/reset-password.php');}}}
$left=max(0,60-(time()-(int)($_SESSION['reset_last_sent']??0)));$note=$_SESSION['flash_otp']??'';unset($_SESSION['flash_otp']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/assets/style.css?v=22"></head><body class="auth-body"><div class="auth-wrap"><a class="brand auth-brand" href="/"><img src="/assets/shadril-logo.png" style="width:44px;height:44px;object-fit:contain;border-radius:10px" alt=""> Shadril Shopping Store</a><div class="auth-page-back"><?=back_button('Previous page')?></div><div class="auth-card auth-special otp-card"><div class="auth-icon">✉️</div><span class="eyebrow">EMAIL VERIFICATION</span><h1>Enter your OTP</h1><p>We sent a 6-digit verification code to your registered email. The code expires in 10 minutes.</p><?php if($note): ?><div class="flash success"><?=e($note)?></div><?php endif;?><?php if($errors): ?><div class="errors"><?=e($errors[0])?></div><?php endif;?><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="action" value="verify"><label>6-digit OTP<input name="otp" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" required autofocus style="font-size:26px;letter-spacing:8px;text-align:center"></label><button class="btn primary full">Verify OTP</button></form><form method="post" id="resendForm"><?=csrf_field()?><input type="hidden" name="action" value="resend"><button id="resendBtn" class="btn ghost full" type="submit" <?= $left>0?'disabled':'' ?>>Resend OTP <span id="timer"><?= $left>0?'('.$left.'s)':'' ?></span></button></form><a class="btn home-return full" href="/">Return to homepage</a></div></div><script>let left=<?=$left?>,t=document.getElementById('timer'),b=document.getElementById('resendBtn');if(left>0){let i=setInterval(()=>{left--;t.textContent=left>0?'('+left+'s)':'';if(left<=0){clearInterval(i);b.disabled=false;}},1000);}</script></body></html>